      licenseUrl: "https://www.loc.gov/pictures/item/2004672786/",
      attribution: "Doris Ulmann, Florence R. Sabin, photogravure, c1922. Library of Congress, Prints and Photographs Division, LC-USZ62-10273.",
      attributionUrl: "https://www.loc.gov/pictures/item/2004672786/",
