    isLiving: false,
    era: "early_modern",
    nationalityCodes: ["PT"],
    regionCode: "southern_europe",
    occupationIds: ["navigator", "explorer"],
    fieldIds: ["exploration"],
    impactDomains: ["historical"],
    tagIds: ["explorer"],
